import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_swish_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gemm_swish_kernel(const float* __restrict__ x,
                                  const float* __restrict__ w,
                                  const float* __restrict__ bias,
                                  float* __restrict__ out,
                                  int B, int M, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * N) {
        int b = idx / N;
        int n = idx % N;
        float val = 0.0f;
        for (int m = 0; m < M; m++) {
            val += x[b * M + m] * w[n * M + m];
        }
        val += bias[n];
        float s = 1.0f / (1.0f + expf(-val));
        out[b * N + n] = val * s;
    }
}

torch::Tensor gemm_swish_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor bias) {
    auto B = x.size(0);
    auto M = x.size(1);
    auto N = w.size(0);

    auto out = torch::zeros({B, N}, x.options());

    int total = B * N;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    gemm_swish_kernel<<<gridSize, blockSize>>>(x.data_ptr<float>(),
                                               w.data_ptr<float>(),
                                               bias.data_ptr<float>(),
                                               out.data_ptr<float>(),
                                               B, M, N);

    return out;
}
"""

gemm_swish_cpp_source = "torch::Tensor gemm_swish_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor bias);"

gemm_swish = load_inline(
    name="gemm_swish",
    cpp_sources=gemm_swish_cpp_source,
    cuda_sources=gemm_swish_source,
    functions=["gemm_swish_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_features)

    def forward(self, x):
        x = gemm_swish.gemm_swish_cuda(x, self.weight, self.bias)
        x = self.group_norm(x)
        return x

batch_size = 128
in_features = 512
out_features = 1024
num_groups = 32
bias_shape = (out_features,)

def get_inputs():
    return [torch.randn(batch_size, in_features).cuda()]

def get_init_inputs():
    return [in_features, out_features, num_groups, bias_shape]
